/* ------------------------------------------------------------------ RNG */
static uint64_t rs;
static uint32_t ru (void) { rs ^= rs >> 12; rs ^= rs << 25; rs ^= rs >> 27; return (uint32_t)((rs * 2685821657736338717ULL) >> 32); }
static float rf (float lo, float hi) { return lo + (hi - lo) * (ru () / 4294967296.0f); }
static int ri (int lo, int hi) { return lo + (int)(ru () % (uint32_t)(hi - lo + 1)); }

/* -------------------------------------------------------- call logging */
static char logbuf[1 << 16];
static int loglen;
static void logf_ (const char *fmt, ...)
{
	va_list ap;
	va_start (ap, fmt);
	int n = vsnprintf (logbuf + loglen, sizeof logbuf - loglen, fmt, ap);
	va_end (ap);
	if (n > 0) loglen = loglen + n < (int)sizeof logbuf ? loglen + n : (int)sizeof logbuf - 1;
}
static long EI (edict_t *e) { return e ? (long)(e - g_edicts) : -1; }   /* edict as index */
#define V3 "(%a,%a,%a)"
#define VA(v) (v) ? (v)[0] : 0.0f, (v) ? (v)[1] : 0.0f, (v) ? (v)[2] : 0.0f

static uint32_t hash_bytes (uint32_t h, const void *p, size_t n)
{
	const unsigned char *c = p;
	while (n--) h = (h ^ *c++) * 16777619u;
	return h;
}
static uint32_t hash_str (const char *s) { return s ? hash_bytes (2166136261u, s, strlen (s)) : 0; }

