/* deterministic fake world: result is a pure function of the arguments */
static trace_t m_trace (vec3_t start, vec3_t mins, vec3_t maxs, vec3_t end, edict_t *pass, int mask)
{
	trace_t t;
	vec3_t z = {0, 0, 0};
	uint32_t h = 2166136261u;
	h = hash_bytes (h, start, 12); h = hash_bytes (h, end, 12);
	h = hash_bytes (h, mins ? mins : z, 12); h = hash_bytes (h, maxs ? maxs : z, 12);
	long pi = EI (pass); h = hash_bytes (h, &pi, sizeof pi); h = hash_bytes (h, &mask, sizeof mask);
	memset (&t, 0, sizeof t);
	static const float fr[] = {1.0f, 1.0f, 1.0f, 0.0f, 0.25f, 0.5f, 0.75f, 1.0f};
	t.fraction = fr[h & 7];
	t.allsolid = (h >> 3) % 31 == 0;
	t.startsolid = t.allsolid || (h >> 8) % 23 == 0;
	for (int i = 0; i < 3; i++) t.endpos[i] = start[i] + t.fraction * (end[i] - start[i]);
	t.plane.normal[2] = 1;
	t.surface = &surf_none;
	t.contents = t.fraction < 1 ? CONTENTS_SOLID : 0;
	t.ent = t.fraction < 1 && globals.num_edicts > 1 ? &g_edicts[(h >> 13) % globals.num_edicts] : g_edicts;
	logf_ ("trace " V3 " " V3 " " V3 " " V3 " %ld %d -> %a %ld\n", VA (start), VA (mins), VA (maxs), VA (end), pi, mask, t.fraction, EI (t.ent));
	return t;
}
static int m_pointcontents (vec3_t p)
{
	uint32_t h = hash_bytes (2166136261u, p, 12);
	static const int c[] = {0, 0, 0, 0, 0, CONTENTS_WATER, CONTENTS_SLIME, CONTENTS_LAVA, CONTENTS_SOLID, CONTENTS_WINDOW};
	int r = c[h % 10];
	logf_ ("pointcontents " V3 " -> %d\n", VA (p), r);
	return r;
}
