/* cvars: fixed table, unknown names default to "0" */
static struct { const char *name, *value; } cvar_defaults[] = {
	{"maxclients", "1"}, {"maxentities", "64"}, {"deathmatch", "0"}, {"coop", "0"}, {"skill", "1"},
	{"sv_gravity", "800"}, {"sv_maxvelocity", "2000"}, {"sv_rollspeed", "200"}, {"sv_rollangle", "2"},
	{"filterban", "1"}, {"flood_msgs", "4"}, {"flood_persecond", "4"}, {"flood_waitdelay", "10"},
};
static cvar_t cvars[128];
static int ncvars;
static cvar_t *m_cvar (char *name, char *value, int flags)
{
	for (int i = 0; i < ncvars; i++) if (!strcmp (cvars[i].name, name)) return &cvars[i];
	const char *v = "0";
	for (unsigned i = 0; i < sizeof cvar_defaults / sizeof cvar_defaults[0]; i++) if (!strcmp (cvar_defaults[i].name, name)) v = cvar_defaults[i].value;
	cvar_t *c = &cvars[ncvars++];
	c->name = strdup (name); c->string = strdup (v); c->value = atof (v); c->flags = flags;
	return c;
}
static cvar_t *m_cvar_set (char *n, char *v) { logf_ ("cvar_set %s %s\n", n, v); return m_cvar (n, v, 0); }
